from pathlib import Path
import json, re
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH as A
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT = Path(__file__).resolve().parents[1]
env = json.loads((ROOT/'artifacts/environment.json').read_text(encoding='utf-8'))
results = json.loads((ROOT/'artifacts/results.json').read_text(encoding='utf-8'))
records = []
def walk(suites):
    for s in suites:
        for spec in s.get('specs', []):
            for test in spec['tests']:
                r = test['results'][-1]
                records.append((spec['title'].split(':')[0], spec['title'], r['status'], r['duration']))
        walk(s.get('suites', []))
walk(results['suites'])
assert len(records) == 17 and all(r[2] == 'passed' for r in records)
duration = results['stats']['duration']/1000
d = Document()
sec=d.sections[0]
sec.page_width=Cm(21); sec.page_height=Cm(29.7)
sec.left_margin=Cm(2.5); sec.right_margin=Cm(1.5)
sec.top_margin=sec.bottom_margin=Cm(1.5)
for name in ['Normal','Heading 1','Heading 2']:
    s=d.styles[name]; s.font.name='Times New Roman'; s.font.size=Pt(14)
    s.font.color.rgb=RGBColor(0,0,0); s.font.italic=False
    s.font.bold=name!='Normal'
    f=s.paragraph_format; f.line_spacing=1.5; f.space_before=f.space_after=Pt(0)
    f.first_line_indent=Cm(0 if name=='Heading 1' else 1.25)
    f.alignment=A.LEFT if name!='Normal' else A.JUSTIFY
    f.page_break_before=False
    rp=s.element.get_or_add_rPr(); lang=OxmlElement('w:lang'); lang.set(qn('w:val'),'uk-UA'); rp.append(lang)
    fonts=rp.find(qn('w:rFonts'))
    if fonts is not None:
        for attr in ['asciiTheme','hAnsiTheme','eastAsiaTheme','cstheme']:
            fonts.attrib.pop(qn('w:'+attr),None)
        for attr in ['ascii','hAnsi','eastAsia','cs']: fonts.set(qn('w:'+attr),'Times New Roman')
d.core_properties.author='Жуков Михайло Володимирович'
d.core_properties.title='Лабораторна робота № 7. Складні сценарії взаємодії з інтерфейсом. Варіант 1'
counts={'Таблиця':0,'Рисунок':0,'Лістинг':0}
def p(text='',align=None,bold=False):
    x=d.add_paragraph(); x.add_run(text).bold=bold
    if align is not None: x.alignment=align; x.paragraph_format.first_line_indent=Cm(0)
    return x
def h(text,level=1,center=False):
    x=d.add_paragraph(text,style=f'Heading {level}')
    if center: x.alignment=A.CENTER
    return x
def caption(kind,text):
    counts[kind]+=1
    x=p(f'{kind} {counts[kind]} - {text}',A.CENTER)
    x.paragraph_format.space_before=Pt(6 if kind=='Таблиця' else 0)
    x.paragraph_format.space_after=Pt(8 if kind=='Рисунок' else 6 if kind=='Лістинг' else 0)
def table(headers,rows,title,widths=None):
    t=d.add_table(rows=1,cols=len(headers));t.style='Table Grid';t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    widths=widths or [17/len(headers)]*len(headers)
    for col,w in zip(t.columns,widths):col.width=Cm(w)
    for i,text in enumerate(headers):t.rows[0].cells[i].text=str(text)
    for row in rows:
        for cell,text in zip(t.add_row().cells,row):cell.text=str(text)
    borders=OxmlElement('w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:
        e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'000000');borders.append(e)
    t._tbl.tblPr.append(borders)
    for ri,row in enumerate(t.rows):
        no=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(no)
        if ri==0:row._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
        for i,c in enumerate(row.cells):
            c.width=Cm(widths[i])
            if ri==0:
                shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'D9E2F3');c._tc.get_or_add_tcPr().append(shade)
            for x in c.paragraphs:
                f=x.paragraph_format;f.first_line_indent=Cm(0);f.line_spacing=1;f.space_before=f.space_after=Pt(0)
                x.alignment=A.CENTER if ri==0 else A.LEFT
                for r in x.runs:r.font.name='Times New Roman';r.font.size=Pt(10 if len(headers)>=6 else 12);r.bold=ri==0
    for x in t.rows[-1].cells:
        for para in x.paragraphs:para.paragraph_format.keep_with_next=True
    caption('Таблиця',title)
def listing(code,title):
    for line in code.strip('\n').splitlines():
        x=p(line,A.LEFT);x.paragraph_format.line_spacing=1;x.paragraph_format.keep_with_next=True
        for r in x.runs:r.font.name='Consolas';r.font.size=Pt(9)
    caption('Лістинг',title)
def snippet(file,start,end,title):
    lines=(ROOT/'tests'/file).read_text(encoding='utf-8').splitlines()
    listing('\n'.join(lines[start-1:end]),title+' ('+file+')')
def picture(file,title):
    x=p('',A.CENTER);x.paragraph_format.keep_with_next=True
    x.add_run().add_picture(str(ROOT/'artifacts'/file),width=Cm(16.5));caption('Рисунок',title)
def titleline(text='',bold=False,align=A.CENTER):
    x=p(text,align,bold);x.paragraph_format.line_spacing=Pt(21)
    return x
for text in ['Державний вищий навчальний заклад','Ужгородський національний університет','Факультет інформаційних технологій']:titleline(text,True)
for _ in range(6):titleline()
titleline('Лабораторна робота № 7',True)
x=titleline();x.add_run('Тема: ').bold=True;x.add_run('«Складні сценарії взаємодії з інтерфейсом. Форми, таблиці, діалоги, файли, вкладки та фрейми»')
for _ in range(7):titleline()
for text in ['Виконав студент IV курсу','Спеціальності «Інженерія','програмного забезпечення»','Жуков Михайло Володимирович']:titleline(text,False,A.RIGHT)
for _ in range(11):titleline()
titleline('Ужгород-2026',True)
d.add_page_break()

h('1. Мета, завдання та інструменти')
p('Я виконав лабораторну роботу з дисципліни «Автоматизація тестування». Мета - навчитися перевіряти складні дії користувача в браузері: форми, таблиці, діалоги, файли, вкладки, фрейми та динамічний вміст. Індивідуальне завдання - варіант 1, додавання п’яти елементів і видалення двох на сторінці /add_remove_elements/.')
p('Я підготував 15 тестів за кроками 2-7 методички й два незалежні тести варіанта 1. Перевірки виконані в Chromium на зовнішньому стенді https://the-internet.herokuapp.com. Повний код здається окремо; у звіті я навів фрагменти, які пояснюють ключові рішення.')
p('Фактичні версії середовища я зберіг у файлі artifacts/environment.json. У таблиці 1 наведено інструменти прогону.')
table(['Інструмент','Версія / налаштування'],[['ОС',env['os']],['Node.js',env['node']],['TypeScript',env['typescript']],['Playwright Test',env['playwright']],['Chromium',env['browser']],['Виконання','2 workers; retries: 0; timeout тесту: 45 с'],['Очікування','expect: 10 с; дія: 15 с; динамічна поява: 15 с']], 'Середовище виконання',[5,12])
p('Репозиторій роботи: https://github.com/MikhailZhukov-lab/automation-lab2/tree/7. Вихідні файли та матеріали прогону розміщено в гілці 7.')

h('2. Принципи взаємодії з браузером')
p('Для елементів сторінки я використав локатори й очікувальні твердження. Локатор повторно знаходить елемент під час дії, а твердження очікує потрібний стан у межах timeout. Діалоги, завантаження та нові вкладки обробляються через події браузера [2-6].')
p('Метод check() установлює прапорець і залишає його встановленим при повторному виклику. Метод click() перемикає поточний стан. Якщо прапорець уже встановлений, повторний click() зніме його; тому для заданого результату я обрав check() та uncheck().')
p('У таблиці 2 я зіставив типи взаємодії зі способом перевірки. Так легше відокремити DOM-елементи від подій і окремих документів.')
table(['Об’єкт','Дія','Перевірка'],[['Список','selectOption()','toHaveValue(), toHaveText()'],['Прапорець','check(), uncheck()','toBeChecked()'],['Повзунок','Home, ArrowRight','Значення поля та #range'],['Таблиця','Читання комірок, click() заголовка','toHaveCount(), expect.poll()'],['Діалог','once(), accept(), dismiss()','Текст #result'],['Файл','setInputFiles(), saveAs()','Назва та ненульовий розмір'],['Вкладка / фрейм','waitForEvent(), frameLocator()','Заголовок / текст редактора']], 'Дії та способи перевірки',[3.5,6,7.5])
p('Обробник події я реєструю до натискання. Проміс очікування створюється одразу, але await застосовую вже після дії. Інакше виконання може зупинитися до натискання або пропустити подію. Нижче наведено обидва порядки дій [2, 3].')
listing("// Неправильно: подія може вже відбутися.\nawait link.click();\nconst lost = await page.waitForEvent('download');\n// Правильно: очікування зареєстровано заздалегідь.\nconst pending = page.waitForEvent('download');\nawait link.click();\nconst download = await pending;",'Порядок реєстрації очікування події')

